#include <glm/glm.hpp>
#include <algorithm>
#include <cmath>

#include "enemy_ai_shared.h"

namespace ptv {

static ptv::Vec3 estimate_forward_from_rotation(const ptv::Quat& q) {
    // Assuming engine's Quat is w,x,y,z; forward = rotate (0,0,1)
    // Minimal placeholder: face towards +Z ignoring rotation specifics
    (void)q; return ptv::Vec3{0.0f, 0.0f, 1.0f};
}

void ptv_ai_tick_drone(World& w, std::uint32_t e, EnemyStateLocal& s, float dt) {
    if (!w.has<CTransform>(e)) return;
    auto& tr = w.get<CTransform>(e).t;

    // Desired ring: 6-12m
    const float minR = 6.0f;
    const float maxR = 12.0f;
    ptv::Vec3 center = s.last_player_pos;

    // Maintain altitude around player's head height + offset
    float desiredY = std::max(center.y + 1.0f, 2.0f + s.desired_altitude);

    // Orbit progression and strafing
    s.orbit_angle = ptv_ai_angle_wrap(s.orbit_angle + dt * 0.6f);
    float radius = minR + 0.5f * (maxR - minR) * (1.0f + std::sin(0.7f * s.orbit_angle));

    // Separation: repel from nearby drones (simple)
    ptv::Vec3 sep{0.0f, 0.0f, 0.0f};
    int sep_count = 0;
    auto& reg = w.registry();
    auto v = reg.view<ptv::CTransform, ptv::CTag>();
    for (auto other : v) {
      auto oid = static_cast<std::uint32_t>(other);
      if (oid == e) continue;
      if (!w.has<ptv::CTag>(oid)) continue;
      const auto& tg = w.get<ptv::CTag>(oid);
      if (!ptv_ai_has_tag(tg, "enemy")) continue;
      if (!ptv_ai_has_tag(tg, "flying")) continue;
      const auto& otr = w.get<ptv::CTransform>(oid).t;
      ptv::Vec3 d = tr.position - otr.position;
      float d2 = glm::dot(d, d);
      if (d2 < 4.0f) { // within 2m
        float inv = 1.0f / std::max(std::sqrt(std::max(d2, 1e-4f)), 0.2f);
        sep += inv * d;
        sep_count++;
      }
    }
    if (sep_count > 0) sep = (1.0f / static_cast<float>(sep_count)) * sep;

    // Dodge when recently tagged by beam effect
    if (w.has<CTag>(e)) {
        const auto& tg = w.get<CTag>(e);
        if (ptv_ai_has_tag(tg, "beam_sustained_on_enemy") && s.t.dodge_cooldown <= 0.0f) {
            s.orbit_angle += 1.57f; // quarter turn burst
            s.t.dodge_cooldown = 1.0f;
        }
    }

    // Target orbital point plus separation
    ptv::Vec3 orbit_pos = ptv_ai_orbit_point(center, radius, s.orbit_angle, desiredY);
    orbit_pos += 0.6f * sep; // bias away from neighbors

    // Step towards point with hover speed
    float speed = 6.0f; // m/s readable
    ptv::Vec3 next = ptv_ai_seek(tr.position, orbit_pos, speed * dt);
    tr.position = next;

    // Fire bursts if within frontal cone (readability: tracers handled by VFX systems)
    ptv::Vec3 fwd = estimate_forward_from_rotation(tr.rotation);
    if (ptv_ai_in_cone(tr.position, fwd, center, 25.0f, 20.0f)) {
        if (s.t.fire_cooldown <= 0.0f) {
            ptv_ai_add_tag(w, e, "ai.fire_burst");
            s.t.fire_cooldown = 1.2f; // short bursts cadence
        }
    } else {
        ptv_ai_remove_tag(w, e, "ai.fire_burst");
    }
}

} // namespace ptv

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <entt/entt.hpp>
#include <glm/glm.hpp>
#include <algorithm>
#include <cmath>

#include "enemy_ai_shared.h"

namespace ptv {

void ptv_ai_tick_raider(World& w, std::uint32_t e, EnemyStateLocal& s, float dt) {
    if (!w.has<CTransform>(e)) return;
    auto& tr = w.get<CTransform>(e).t;

    // Prefer readable lateral flanks, never teleport behind
    ptv::Vec3 player = s.last_player_pos;
    ptv::Vec3 dir = player - tr.position;
    float d2 = glm::dot(dir, dir);
    float d = std::sqrt(std::max(d2, 1e-6f));
    ptv::Vec3 toP = (1.0f / d) * dir;

    // Choose a lateral offset target mimicking a cover hop
    ptv::Vec3 right{toP.z, 0.0f, -toP.x}; // simple right vector on ground plane
    float flank_sign = ((e & 1u) ? 1.0f : -1.0f);
    float desired_range = 9.0f; // keep some distance, peek-fire

    ptv::Vec3 cover_like = player - toP * desired_range + right * flank_sign * 2.5f;
    cover_like.y = 0.0f; // ground

    // If close (<3.2m), attempt melee charge forward
    bool charge = (d < 3.2f);

    float speed = charge ? 6.5f : 3.2f; // readable ground speeds
    tr.position = ptv_ai_seek(tr.position, charge ? (player - toP * 0.8f) : cover_like, speed * dt);

    // Grenade occasionally when mid-range and cooldown ready
    if (!charge && d > 6.0f && d < 14.0f && s.t.fire_cooldown <= 0.0f) {
        ptv_ai_add_tag(w, e, "ai.throw_grenade"); // VFX/logic elsewhere reads this
        s.t.fire_cooldown = 4.0f;
    } else {
        ptv_ai_remove_tag(w, e, "ai.throw_grenade");
    }

    // Focus-fire dome shield: if self has a tag hint set by shield system, burst
    if (w.has<CTag>(e)) {
        const auto& tg = w.get<CTag>(e);
        if (ptv_ai_has_tag(tg, "player_dome_nearby")) {
            ptv_ai_add_tag(w, e, "ai.focus_fire");
        } else {
            ptv_ai_remove_tag(w, e, "ai.focus_fire");
        }
    }
}

} // namespace ptv

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <entt/entt.hpp>
#include <glm/glm.hpp>
#include <algorithm>
#include <cmath>

#include "enemy_ai_shared.h"

namespace ptv {

void ptv_ai_tick_mech(World& w, std::uint32_t e, EnemyStateLocal& s, float dt) {
    if (!w.has<CTransform>(e)) return;
    auto& tr = w.get<CTransform>(e).t;

    // Slow patrol toward a firing position ~15-20m, then anchor
    ptv::Vec3 player = s.last_player_pos;
    ptv::Vec3 dir = player - tr.position;
    float dist = std::sqrt(std::max(glm::dot(dir, dir), 1e-6f));
    ptv::Vec3 toP = (1.0f / dist) * dir;

    float hold_min = 15.0f, hold_max = 20.0f;
    float desired = 0.5f * (hold_min + hold_max);

    if (dist > hold_max) {
        tr.position = ptv_ai_seek(tr.position, player - toP * desired, 2.0f * dt); // heavy slow
        ptv_ai_remove_tag(w, e, "ai.anchor");
    } else if (dist < hold_min) {
        tr.position = ptv_ai_seek(tr.position, player - toP * desired, 2.0f * dt);
        ptv_ai_remove_tag(w, e, "ai.anchor");
    } else {
        // Anchor and volley
        ptv_ai_add_tag(w, e, "ai.anchor");
        if (s.t.fire_cooldown <= 0.0f) {
            ptv_ai_add_tag(w, e, "ai.volley_cannon"); // AOE tell handled by VFX
            s.t.fire_cooldown = 6.0f;
        } else {
            ptv_ai_remove_tag(w, e, "ai.volley_cannon");
        }
    }

    // Ground pound if very close and roughly ground-level
    if (dist < 5.0f && std::abs(tr.position.y) < 1.0f) {
        ptv_ai_add_tag(w, e, "ai.ground_pound");
    } else {
        ptv_ai_remove_tag(w, e, "ai.ground_pound");
    }

    // React to heavy constructs: if tagged, open stagger window
    if (w.has<CTag>(e)) {
        const auto& tg = w.get<CTag>(e);
        if (ptv_ai_has_tag(tg, "hit_by_battering_ram")) {
            s.t.stagger_time = 1.2f; // long stagger for readability
        }
    }
}

} // namespace ptv

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <entt/entt.hpp>
#include <glm/glm.hpp>
#include <algorithm>
#include <cmath>

#include "enemy_ai_shared.h"

namespace ptv {

void ptv_ai_tick_fear(World& w, std::uint32_t e, EnemyStateLocal& s, float dt) {
    if (!w.has<CTransform>(e)) return;
    auto& tr = w.get<CTransform>(e).t;

    // Aggressive rush
    ptv::Vec3 player = s.last_player_pos;
    ptv::Vec3 d = player - tr.position;
    float dist = std::sqrt(std::max(glm::dot(d, d), 1e-6f));
    ptv::Vec3 toP = (1.0f / dist) * d;

    float speed = 5.0f; // fast but readable
    tr.position = ptv_ai_seek(tr.position, player - toP * 1.8f, speed * dt);

    // Ring-drain aura when close
    float aura_range = 4.0f;
    if (dist < aura_range) {
        ptv_ai_add_tag(w, e, "ai.fear_aura_active");
        // We do not have CRingEnergy here; a gameplay layer can read this tag and apply
        // params.value("fear_aura_drain_per_s", 2.0) externally. This AI announces intent.
    } else {
        ptv_ai_remove_tag(w, e, "ai.fear_aura_active");
    }

    // Vulnerable to reinforced cages: if a reinforcement tag exists, reduce local stagger
    if (w.has<CTag>(e)) {
        const auto& tg = w.get<CTag>(e);
        if (ptv_ai_has_tag(tg, "caged_reinforced")) {
            // shorter breakout: emulate by longer stagger when broken
            s.t.stagger_time = std::max(s.t.stagger_time, 0.4f);
        }
    }
}

} // namespace ptv
